// The stdio shim agents launch (`node .ifc-skills/viewer/mcp-shim.mjs`). The
// viewer's tool server listens on a new port with a new token each session,
// so the shim re-reads server.json next to it on every message and forwards
// the JSON-RPC line over HTTP. It has no dependencies and needs Node 18+.
// Written to the project on connect, and removed with the bridge folder.

export const SHIM_SOURCE = `// IFC Viewer MCP shim: forwards stdio JSON-RPC to the running viewer.
// Generated by the IFC Viewer extension; safe to delete (it is recreated on connect).
import { readFile } from 'node:fs/promises';
import { createInterface } from 'node:readline';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const NOT_CONNECTED =
  'The IFC Viewer is not connected. Open the model in VS Code and click Agent in the status bar of the viewer (Connect to agent), then try again.';

async function target() {
  try {
    const info = JSON.parse(await readFile(join(here, 'server.json'), 'utf8'));
    if (info && typeof info.url === 'string' && typeof info.token === 'string') return info;
  } catch {}
  return null;
}

function send(message) {
  process.stdout.write(JSON.stringify(message) + '\\n');
}

function offline(request) {
  const id = request.id;
  if (id === undefined) return null;
  switch (request.method) {
    case 'initialize':
      return { jsonrpc: '2.0', id, result: { protocolVersion: request.params?.protocolVersion ?? '2025-06-18', capabilities: { tools: {} }, serverInfo: { name: 'ifc-viewer (not connected)', version: '0' }, instructions: NOT_CONNECTED } };
    case 'ping':
      return { jsonrpc: '2.0', id, result: {} };
    case 'tools/list':
      return { jsonrpc: '2.0', id, result: { tools: [] } };
    default:
      return { jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: NOT_CONNECTED }], isError: true } };
  }
}

async function forward(line) {
  let request;
  try {
    request = JSON.parse(line);
  } catch {
    return;
  }
  const info = await target();
  if (!info) {
    const answer = offline(request);
    if (answer) send(answer);
    return;
  }
  try {
    const response = await fetch(info.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', authorization: 'Bearer ' + info.token },
      body: line,
    });
    const text = await response.text();
    if (response.status === 202 || !text) return;
    process.stdout.write(text + '\\n');
  } catch {
    const answer = offline(request);
    if (answer) send(answer);
  }
}

const lines = createInterface({ input: process.stdin });
const inflight = new Set();
lines.on('line', (line) => {
  if (!line.trim()) return;
  const job = forward(line).finally(() => inflight.delete(job));
  inflight.add(job);
});
lines.on('close', () => Promise.all(inflight).then(() => process.exit(0)));
`;
